KG_CODE("f:src/autoskill/daemon.py","\"\"\"The daemon: session registry, request router, policy enforcement point.\n\nTransport is a loopback TCP listener plus a shared-secret token written to a\nfile in `AUTOSKILL_HOME`. Windows offers no AF_UNIX in CPython (verified) and\npywin32 named pipes would add a dependency for one call, so loopback + token is\nthe pragmatic choice. It is *not* the only line of defence: every request is\nstill evaluated by the permission engine, so possessing the token does not grant\nthe ability to act silently — in `strict` mode it still requires a human `yes`\nfor every action. Defence in depth is the point.\n\nRequests for one session are serialised. Two clicks racing on the same ref store\nwould let an observation land between a resolve and an act, which is exactly the\nstale-target bug the ref generation exists to prevent.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport os\nimport secrets\nimport socket\nimport socketserver\nimport subprocess\nimport threading\nfrom contextvars import ContextVar\nimport time\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\nfrom typing import Any, Callable\n\nfrom .protocol import (ErrorCode, Method, ProtocolError, Request, Response,\n                       RpcError, PROTOCOL_VERSION, EffectState as LegacyEffectState)\nfrom .contracts import (Action, ActionKind, BudgetEstimate, Component, Effect,\n                        EffectState, EventKind, Failure, FailureKind, IntentClass,\n                        Parameter, SemanticTarget, Sensitivity, SessionEvent)\nfrom .events import EventBus, EventDeliveryError\nfrom .safety.audit import AuditLog\nfrom .safety.fsacl import restrict_to_owner as _restrict_to_owner\nfrom .safety.permissions import (Decision, PermissionEngine, PermissionMode, Risk,\n                                 load_policy, save_policy)\n\nfrom . import __version__ as VERSION\nfrom .paths import endpoint_file, home_dir  # noqa: F401  (re-exported; CM-42)\n\n\ndef _loggable(url: str | None) -> str | None:\n    \"\"\"A URL safe to write to a log that outlives the session.\n\n    The approval prompt may show the whole URL, but the audit entry does\n    not: enterprise query strings carry live session state (measured on a\n    real run: `_adf.ctrl-state`, `_afrLoop` and a worklist task id, all\n    written verbatim to disk). Keep origin and path, drop the rest.\n    \"\"\"\n    if not url or \"://\" not in url:\n        return url\n    head, _, rest = url.partition(\"?\")\n    if rest:\n        head += \"?(query redacted)\"\n    return head[:200]\n\n\n_REQUIRED: dict[str, tuple[str, ...]] = {}\n\n\ndef _required_params(method: str) -> tuple[str, ...]:\n    \"\"\"The method's required parameters, from its toolspec schema.\"\"\"\n    if not _REQUIRED:\n        from .toolspec import TOOLS\n        _REQUIRED.update({t[\"method\"]: tuple(t[\"schema\"].get(\"required\") or ())\n                          for t in TOOLS if t.get(\"method\") and t.get(\"schema\")})\n    return _REQUIRED.get(method, ())\n\n\ndef _surprise_baseline() -> dict[int, int] | None:\n    \"\"\"Visible top-level windows before a desktop action (Win32 only, no COM).\"\"\"\n    if os.name != \"nt\":\n        return None\n    try:\n        from .runcleanup import top_windows\n        return top_windows()\n    except Exception:                           # noqa: BLE001 - observation only\n        return None\n\n\ndef _surprise_windows(base: dict[int, int] | None, proc: str | None) -> list[str]:\n    \"\"\"Titles of windows the target process raised during an action.\n\n    A modal that appears while a desktop action runs is the classic silent\n    blocker: measured 2026-10-06, Excel's 'There's a problem with this\n    formula' dialog swallowed every later input while each individual call\n    still reported success. Naming the window turns the invisible stall into\n    a structured observation (additive `surprise_window` result key).\n    \"\"\"\n    if not base or os.name != \"nt\" or not proc:\n        return []\n    try:\n        import ctypes\n        import psutil\n        from .runcleanup import top_windows\n        now = top_windows()\n        target = (proc or \"\").strip().lower()\n        wanted = set()\n        for pid in set(now.values()):\n            try:\n                if psutil.Process(pid).name().lower() == target:\n                    wanted.add(pid)\n            except Exception:                   # noqa: BLE001 - process gone\n                continue\n        if not wanted:\n            return []\n        user32 = ctypes.WinDLL(\"user32\")\n        titles: list[str] = []\n        for hwnd, pid in now.items():\n            if hwnd in base or pid not in wanted:\n                continue\n            length = user32.GetWindowTextLengthW(hwnd)\n            if length <= 0:\n                continue\n            buf = ctypes.create_unicode_buffer(length + 1)\n            user32.GetWindowTextW(hwnd, buf, length + 1)\n            text = buf.value.strip()\n            if text:\n                titles.append(text[:80])\n        return titles[:4]\n    except Exception:                           # noqa: BLE001 - observation only\n        return []\n\n\n@dataclass\nclass Session:\n    id: str\n    created_at: float = field(default_factory=time.time)\n    lock: Any = field(default_factory=threading.RLock)\n    rb_surface: Any = None\n    ref_store: Any = None          # desktop.refs.RefStore\n    browser: Any = None            # browser.cdp.CdpConnection\n    browser_page: Any = None       # browser.page.Page (the active tab)\n    browser_pages: dict[str, Any] = field(default_factory=dict)  # tab_id -> Page\n    browser_tab_seq: int = 0\n    browser_session_id: str | None = None\n    recording: Any = None\n    last_window: str | None = None\n    last_used: float = field(default_factory=time.time)\n    memory_space: str = \"default\"   # which learned memory this session reads and writes\n    # db1: the agent that owns the session (the MCP client's clientInfo, the\n    # CLI, a replay), shown by the dashboard; and the feed position up to which\n    # this session has heard of the owner's button presses (owner_controls).\n    client: dict[str, Any] = field(default_factory=dict)\n    control_seq: int = 0\n    agent: str = \"\"                 # db7: the agent's name (up the client's process chain, or its MCP name)\n\n    def touch(self) -> None:\n        self.last_used = time.time()\n\n    def idle_s(self) -> float:\n        return time.time() - self.last_used\n\n    def info(self) -> dict[str, Any]:\n        return {\"session_id\": self.id,\n                \"created_at\": self.created_at,\n                \"age_s\": round(time.time() - self.created_at, 1),\n                \"idle_s\": round(self.idle_s(), 1),\n                \"refs\": len(self.ref_store) if self.ref_store else 0,\n                \"browser_attached\": self.browser is not None,\n                \"memory_space\": self.memory_space,\n                \"client\": dict(self.client),\n                \"agent\": self.agent}\n\n\nclass ConfirmationBroker:\n    \"\"\"Holds pending approvals so a human can answer out of band.\n\n    The daemon must never approve on the agent's behalf, and must never block\n    forever: an unanswered request expires as `CONFIRMATION_TIMED_OUT`, which\n    the agent is told to respect rather than retry.\n\n    Pending approvals are also mirrored to <home>/confirmations.json so a\n    headless setup can watch the file (or `auto status`) instead of the\n    daemon's console, where nobody is looking (S88: tokens printed to stdout\n    the user never saw).\n    \"\"\"\n\n    def __init__(self, mirror: Path | None = None) -> None:\n        self._pending: dict[str, dict[str, Any]] = {}\n        self._events: dict[str, threading.Event] = {}\n        self._answers: dict[str, bool] = {}\n        self._lock = threading.Lock()\n        self._mirror = mirror\n\n    def _write_mirror(self) -> None:\n        if self._mirror is None:\n            return\n        try:\n            items = list(self._pending.values())\n            tmp = self._mirror.with_suffix(\".tmp\")\n            tmp.write_text(json.dumps(\n                [{\"token\": i[\"token\"], \"method\": i[\"method\"],\n                  # b5t2c (owner decision A, CUA history.rs:2077-2110):\n                  # the persisted mirror never carries action arguments —\n                  # only the argument-free mirror detail; the live detail\n                  # (with arguments, for the human approving) stays in\n                  # memory and on the live surfaces.\n                  \"detail\": i[\"mirror_detail\"]} for i in items], indent=2),\n                encoding=\"utf-8\")\n            _restrict_to_owner(tmp)\n            os.replace(tmp, self._mirror)\n            # Approval tokens are as sensitive as the endpoint token:\n            # holding one lets a caller answer a pending prompt.\n            _restrict_to_owner(self._mirror)\n        except Exception:\n            pass            # the mirror is advisory; never block a prompt\n\n    def ask(self, *, session: str | None, method: str, detail: str,\n            timeout: int, mirror_detail: str | None = None) -> bool:\n        token = secrets.token_hex(4)\n        ev = threading.Event()\n        # b5t2c: one-string callers (every non-batch ask) mirror their\n        # detail verbatim; only an explicit mirror_detail differs — the\n        # batch producers' argument-free text.\n        mirror = detail if mirror_detail is None else mirror_detail\n        with self._lock:\n            self._pending[token] = {\"token\": token, \"session\": session,\n                                    \"method\": method, \"detail\": detail,\n                                    \"mirror_detail\": mirror,\n                                    \"asked_at\": time.time(),\n                                    \"expires_in\": timeout}\n            self._events[token] = ev\n        self._write_mirror()\n        granted = ev.wait(timeout) and self._answers.get(token, False)\n        with self._lock:\n            self._pending.pop(token, None)\n            self._events.pop(token, None)\n            self._answers.pop(token, None)\n        self._write_mirror()\n        return granted\n\n    def pending(self) -> list[dict[str, Any]]:\n        with self._lock:\n            return list(self._pending.values())\n\n    def answer(self, token: str, granted: bool) -> bool:\n        with self._lock:\n            ev = self._events.get(token)\n            if ev is None:\n                return False\n            self._answers[token] = granted\n        ev.set()\n        return True\n\n\ndef _memory_store(name: str) -> property:\n    \"\"\"A learning store that follows the request's memory space (memspace.py).\n\n    Outside a session, or in a session on the \"default\" space, it is the store\n    the daemon was built with; in a session started with `--memory NAME` or\n    `--new-memory NAME` it is that space's store. Assignments set the default.\n    \"\"\"\n    def get(self: \"Daemon\") -> Any:\n        active = self.__dict__[\"_active_space\"].get() if \"_active_space\" in self.__dict__ else None\n        return getattr(active, name) if active is not None else self.__dict__[\"_default_memory\"][name]\n\n    def set_(self: \"Daemon\", value: Any) -> None:\n        self.__dict__.setdefault(\"_default_memory\", {})[name] = value\n    return property(get, set_)\n\n\nclass Daemon:\n    sites = _memory_store(\"sites\")\n    browser_memory = _memory_store(\"browser_memory\")\n    mind = _memory_store(\"mind\")\n    appmemory = _memory_store(\"appmemory\")\n    workflow_evidence = _memory_store(\"workflow_evidence\")\n\n    @property\n    def memory_home(self) -> Path:\n        \"\"\"Folder of the request's memory space; the home for \"default\".\"\"\"\n        active = self._active_space.get() if hasattr(self, \"_active_space\") else None\n        return active.home if active is not None else self.home\n\n    def space(self, name: str) -> Any:\n        \"\"\"The stores of one memory space, opened once and shared by its sessions.\"\"\"\n        from . import memspace\n        name = memspace.check_name(name)\n        with self._spaces_lock:\n            found = self._spaces.get(name)\n            if found is None:\n                if name == memspace.DEFAULT:\n                    d = self._default_memory\n                    found = memspace.MemorySpace(name, self.home, d[\"sites\"], d[\"browser_memory\"],\n                                                 d[\"mind\"], d[\"appmemory\"], d[\"workflow_evidence\"])\n                else:\n                    found = memspace.open_space(name, memspace.require(self.home, name),\n                                                self.events, history_home=self.home)\n                self._spaces[name] = found\n            return found\n\n    @property\n    def rb(self):\n        active = self._active_rb.get() if hasattr(self, \"_active_rb\") else None\n        return active if active is not None else self._legacy_rb\n\n    @rb.setter\n    def rb(self, value):\n        self._legacy_rb = value\n\n    def __init__(self, home: Path | None = None) -> None:\n        self._surface_lock = threading.RLock()\n        self._active_rb = ContextVar(\"autoskill_rb\", default=None)\n        # Learning stores per memory space (memspace.py); \"default\" is built\n        # below from the home, exactly as before spaces existed.\n        self._active_space: ContextVar[Any] = ContextVar(\"autoskill_memory_space\", default=None)\n        self._default_memory: dict[str, Any] = {}\n        self._spaces: dict[str, Any] = {}\n        self._spaces_lock = threading.Lock()\n        self.home = home or home_dir()\n        self.home.mkdir(parents=True, exist_ok=True)\n        self.policy = load_policy(self.home)\n        self.permissions = PermissionEngine(self.policy)\n        self._policy_mtime = 0.0\n        self.events = EventBus(self.home / \"events.jsonl\")\n        self.audit = AuditLog(self.home / \"audit.jsonl\", bus=self.events)\n        from .workmemory import WorkflowMemory\n        self.workmemory = WorkflowMemory(self.home)\n        from .diagnostics import DiagnosticMemory\n        self.diagnostics = DiagnosticMemory(self.home)\n        self.events.subscribe(self.diagnostics.accept, replay=True)\n        from .orchestrator.workflow_memory import WorkflowMemoryGateway\n        self.workflow_evidence = WorkflowMemoryGateway(self.workmemory, self.events)\n        from .orchestrator.environment import EnvironmentGateway\n        self.environment = EnvironmentGateway(self.workmemory, self.events)\n        from .mind import Mind\n        self.mind = Mind(self.home)\n        from .appmem import AppMemory\n        self.appmemory = AppMemory(self.home)\n        self.confirmations = ConfirmationBroker(self.home / \"confirmations.json\")\n        # The owner's dashboard buttons: pause, stop, approvals, live feed (runcontrol.py).\n        from .runcontrol import RunControl\n        self.run_control = RunControl(self.home)\n        # db8: the human-action Recorder behind the dashboard's Record button. Created eagerly,\n        # lock-free: `_run.state` polls it while a batch may hold the surface lock (recorder.py\n        # imports nothing heavy; its capture threads start only on a Record press).\n        from .recorder import HumanRecorder\n        self.human_recorder = HumanRecorder(self)\n        from .rb import RbSurface\n        # Legacy sessionless CLI surface; explicit sessions get isolated refs.\n        self.rb = RbSurface()\n        # What the tool learns about each site survives the daemon: one\n        # file per host under <home>/sites (sitemem.py).\n        from .sitemem import SiteMemory\n        self.sites = SiteMemory(self.home)\n        self.rb.home = self.home\n        from .orchestrator.browser_memory import BrowserMemoryGateway\n        self.browser_memory = BrowserMemoryGateway(self.sites, self.events)\n        self.rb.memory = self.browser_memory\n        from .orchestrator.research import ResearchGateway\n        self.research = ResearchGateway(self.events)\n        self.rb.research = self.research\n        from .orchestrator.perception import PerceptionGateway\n        self.perception = PerceptionGateway(self.events)\n        self.rb.perception = self.perception\n        # The CUA-style indicator narrator: observes every dispatched action\n        # (desktop and browser verbs alike) and drives the agent-cursor\n        # indicator's badge and chips. Pure subscriber — fail-open, never\n        # raises into the bus, no change to any action path.\n        from .desktop.indicator import IndicatorNarrator\n        self.events.subscribe(IndicatorNarrator(self).accept)\n        self._apply_focus_policy()\n        self.sessions: dict[str, Session] = {}\n        self._sessions_lock = threading.Lock()\n        self.started_at = time.time()\n        self._server: socketserver.TCPServer | None = None\n        self.token = secrets.token_urlsafe(32)\n        self.port = 0\n        self._handlers: dict[str, Callable[[Session | None, dict[str, Any]], dict[str, Any]]] = {}\n        self.idle_timeout_s = float(os.environ.get(\"AUTOSKILL_IDLE_TIMEOUT\", \"600\"))\n        self._stop_idle = threading.Event()\n        self._install_handlers()\n\n    # --- session management -------------------------------------------------\n\n    def new_session(self, memory: str | None = None, new_memory: str | None = None,\n                    client: dict[str, Any] | None = None) -> Session:\n        \"\"\"Start a session on a memory space: the saved \"default\", a saved\n        space by name (`memory`), or a new empty space (`new_memory`).\n        `client` names the agent that owns it (db1): name, version, pid.\"\"\"\n        from . import memspace\n        from .desktop.refs import RefStore\n        self.events.ensure_producer_allowed()\n        client = {k: (str(v)[:80] if k != \"pid\" else int(v)) for k, v in dict(client or {}).items()\n                  if k in (\"name\", \"version\", \"pid\") and v not in (None, \"\")}\n        agent = \"\"\n        try:                    # db6: every agent that works with the tool here is remembered (agentsmem.py)\n            from . import agents_cli, agentsmem\n            agentsmem.seen_client(self.home, client)\n            # db7: the agent's own name - up the client process's chain (an agent working through the CLI), else\n            # its MCP client name; the tool's own replay keeps its name\n            if client.get(\"name\") != \"path.run\":\n                agent = agents_cli.agent_of(client.get(\"pid\")) or agents_cli.display_name(client.get(\"name\", \"\"))\n            agent = \"\" if agent == \"cli\" else agent\n            if agent and client.get(\"name\") in (None, \"\", \"cli\"):    # an MCP client is already remembered by name\n                agentsmem.seen_agent(self.home, agent)\n        except Exception:       # noqa: BLE001 - a session never fails for its note in the agents list\n            pass\n        if memory and new_memory:\n            raise ProtocolError(ErrorCode.UNSUPPORTED,\n                                \"choose either a saved memory space or a new one, not both\")\n        if new_memory:\n            space_name = memspace.check_name(new_memory)\n            memspace.create(self.home, space_name)\n        else:\n            space_name = memspace.check_name(memory or memspace.DEFAULT)\n            memspace.require(self.home, space_name)\n        self.space(space_name)       # open it now, so a broken space fails here\n        with self._sessions_lock:\n            for _ in range(200):\n                sid = \"\".join(secrets.choice(\"abcdefghijklmnopqrstuvwxyz\")\n                              for _ in range(4))\n                if sid not in self.sessions:\n                    break\n            else:\n                raise ProtocolError(ErrorCode.INTERNAL, \"cannot allocate session id\")\n            s = Session(id=sid, ref_store=RefStore(), memory_space=space_name, client=client,\n                        control_seq=self.run_control.seq, agent=agent)\n            self.sessions[sid] = s\n            try:\n                with self.events.step(sid, sid) as context:\n                    self.events.emit(EventKind.SESSION_STARTED, SessionEvent(context))\n            except EventDeliveryError:\n                # The start is durable even though notification failed. Preserve\n                # the session so journal and registry agree; RPC reports UNKNOWN,\n                # and session.list lets the caller reconcile instead of retrying.\n                raise\n            except Exception:\n                # A start not acknowledged by the journal is not a usable session.\n                self.sessions.pop(sid, None)\n                raise\n            return s\n\n    def scratch_session(self) -> Session:\n        \"\"\"db7 Phase 1: a session that is never registered, for the studio's reads (Check on screen, Choose from the\n        window): no session event, no run, no history entry.\"\"\"\n        from .desktop.refs import RefStore\n        return Session(id=\"studio\", ref_store=RefStore())\n\n    def get_session(self, sid: str | None) -> Session:\n        if not sid:\n            raise ProtocolError(\n                ErrorCode.NO_SESSION, \"this command needs --session <id>\",\n                hint=\"Start one with `auto session start`.\")\n        s = self.sessions.get(sid)\n        if s is None:\n            known = \", \".join(self.sessions) or \"none\"\n            raise ProtocolError(\n                ErrorCode.NO_SESSION, f\"unknown session {sid!r}\",\n                hint=f\"Open sessions: {known}. Never guess a session id.\")\n        return s\n\n    def stop_session(self, sid: str) -> dict[str, Any]:\n        self.events.ensure_producer_allowed()\n        with self._surface_lock:\n            return self._stop_session_locked(sid)\n\n    def _stop_session_locked(self, sid: str) -> dict[str, Any]:\n        with self._sessions_lock:\n            s = self.sessions.pop(sid, None)\n        if s is None:\n            raise ProtocolError(ErrorCode.NO_SESSION, f\"unknown session {sid!r}\")\n        # Keep the SHAPE of the work before the state goes. Refs, tabs\n        # and the profile lock are worthless once the screen changes;\n        # the ordered recipe is what a person wants months later.\n        kept = None\n        try:\n            from .history import record\n            kept = record(self.home, sid, self.audit.tail(5000, sid), memory_space=s.memory_space)\n        except Exception:\n            pass            # history is a convenience; never block a stop\n        # A ref is a claim about a screen, and the claim expires with the\n        # task. The real-browser surface is sessionless, so nothing else\n        # would ever drop its refs: measured, `rb.click @e1` was still\n        # accepted after every session had been stopped.\n        dropped = {}\n        try:\n            surface = s.rb_surface\n            if surface is not None:\n                other_tabs = set().union(*(getattr(v.rb_surface, \"_owned_tabs\", set())\n                                         for v in self.sessions.values()))\n                dropped = surface.stop(exclude_tabs=other_tabs)\n            elif not self.sessions:\n                dropped = self.rb.reset()\n        except Exception as exc:\n            dropped[\"cleanup_errors\"] = [type(exc).__name__]\n        # Independent component cleanup must survive a broken browser bridge.\n        if not self.sessions:\n            try:\n                from .desktop import overlay\n                overlay.release()   # perf1: the pointer goes, the renderer stays (CUA remove_cursor)\n            except Exception as exc:\n                dropped.setdefault(\"cleanup_errors\", []).append(type(exc).__name__)\n        if s.recording is not None:\n            try:\n                s.recording.stop(save=False)\n            except Exception as exc:\n                dropped.setdefault(\"cleanup_errors\", []).append(type(exc).__name__)\n            s.recording = None\n        # Screenshots of the user's screen, taken without an explicit\n        # path, live here and go with the session.\n        scratch_removed = 0\n        try:\n            import shutil\n            scratch = self.home / \"scratch\" / sid\n            if scratch.exists():\n                scratch_removed = len(list(scratch.rglob(\"*\")))\n                shutil.rmtree(scratch, ignore_errors=True)\n        except Exception:\n            pass\n        if s.browser is not None:\n            try:\n                from .browser import reaper\n                reaper.unregister(self.home, s.browser.browser_pid)\n                s.browser.close()\n            except Exception:\n                pass\n        out: dict[str, Any] = {\n            \"stopped\": sid, \"state_cleared\": True,\n            \"rb_refs_dropped\": dropped.get(\"refs_dropped\", 0),\n            \"cleanup_errors\": dropped.get(\"cleanup_errors\", []),\n            \"scratch_files_removed\": scratch_removed}\n        if kept is not None:\n            out[\"history\"] = str(kept)\n            out[\"note\"] = (\"Working state is gone; a compact record of \"\n                           \"what was done is kept. `auto history show \"\n                           f\"{kept.stem}` reads it back.\")\n        from .handlers import _cua_lifecycle\n        out.update(_cua_lifecycle(\"session_end\", {\"session\": sid}))\n        with self.events.step(sid, sid) as context:\n            self.events.emit(EventKind.SESSION_STOPPED, SessionEvent(context))\n        return out\n\n    # --- request dispatch ---------------------------------------------------\n\n    def _apply_focus_policy(self) -> None:\n        \"\"\"Whether the tool may take the screen, on both surfaces.\n\n        One switch, because a user who asks for quiet means quiet -\n        both surfaces must avoid shared input and foreground activation.\n        \"\"\"\n        steal = bool(getattr(self.policy, \"steal_focus\", False))\n        try:\n            self.rb.focus_windows = steal\n        except Exception:\n            pass\n        try:\n            from .desktop import actions\n            actions.RESTORE_FOREGROUND = not steal\n        except Exception:\n            pass\n\n    def _reload_policy_if_changed(self) -> None:\n        \"\"\"Pick up a policy the user edited outside the daemon.\n\n        The mode is owned by whoever has the shell, not by the agent, so it is\n        written straight to the file. Re-reading it per request keeps a running\n        daemon from serving a stale, more permissive policy.\n        \"\"\"\n        try:\n            mtime = (self.home / \"policy.json\").stat().st_mtime\n        except OSError:\n            return\n        if mtime != self._policy_mtime:\n            self._policy_mtime = mtime\n            self.policy = load_policy(self.home)\n            self.permissions = PermissionEngine(self.policy)\n            self._apply_focus_policy()\n\n    def _idle_loop(self) -> None:\n        \"\"\"Close sessions nobody is using.\n\n        A leaked session is not just untidy: it keeps a browser process and a\n        profile lock alive, which makes the *next* `browser open` fail. Agents\n        are told to stop their sessions, but an agent that crashes mid-task\n        never will, so the daemon needs its own safety net.\n        \"\"\"\n        while not self._stop_idle.wait(30.0):\n            # perf1: the journal and audit become durable here, CUA's 30 s maintenance checkpoint (history.rs:55).\n            # A failed sync must not stop the session reaper; the next tick retries it.\n            for durable in (self.events, self.audit):\n                try:\n                    durable.sync()\n                except OSError:\n                    pass\n            # A flow process that ended is the end of its run (runcontrol.py).\n            self.run_control.end_if_idle(len(self.sessions))\n            if self.idle_timeout_s <= 0:\n                continue\n            for sid, sess in list(self.sessions.items()):\n                if sess.idle_s() > self.idle_timeout_s:\n                    try:\n                        with self._surface_lock:\n                            if sess.idle_s() <= self.idle_timeout_s:\n                                continue\n                            self.stop_session(sid)\n                        self.audit.record(\n                            session=sid, method=\"session.idle_timeout\",\n                            params={\"idle_s\": round(sess.idle_s(), 1)},\n                            outcome=\"ok\", effect_state=\"committed\",\n                            elapsed_ms=0)\n                    except Exception:\n                        pass\n\n    # Connection plumbing, not operations. Logging them buried the real work\n    # under 200 pings in a 400-entry trace.\n    # The dashboard reads the run's state twice a second (runcontrol.py).\n    # t5f F7: and its steps panel reads the run's last turns each time a step lands.\n    NOT_AUDITED = {\"system.ping\", \"_run.state\", \"_run.turns\"}\n\n    def handle(self, req: Request) -> Response:\n        from .contracts import validate_request\n        try:\n            validate_request({\"method\": req.method, \"params\": req.params, \"session\": req.session})\n        except ValueError as exc:\n            return Response.failure(req.id, RpcError(ErrorCode.UNSUPPORTED, str(exc)), time.monotonic())\n        # Physical input is serial even across sessions. Confirmation replies\n        # and read-only monitoring must remain callable while input awaits a user.\n        physical = (req.method.startswith((\"desktop.\", \"browser.\", \"rb.\", \"site.\"))\n                    and req.method not in (\"rb.status\", \"rb.tabs\"))\n        session = self.sessions.get(req.session) if req.session else None\n        # The owner's Pause and Stop buttons (runcontrol.py): a paused request\n        # waits here, before the surface lock, so control frames still pass.\n        try:\n            read_only = self.permissions.risk_of(req.method) is Risk.READ\n            self.run_control.gate(req.method, read_only=read_only)\n            # Acting outside any run (no session, a tool called on its own) is a\n            # run too: the dashboard shows it and its buttons reach it (DB-07).\n            from .runcontrol import RUN_STARTS\n            if (self.run_control.acts(req.method, read_only) and req.method not in RUN_STARTS\n                    and not req.method.startswith((\"_\", \"session.\", \"site.replay\", \"config.\"))\n                    and self.run_control.activity(req.method)):\n                self.run_control.open_dashboard(\"activity\")\n        except ProtocolError as exc:\n            self.run_control.note_request(method=req.method, session=req.session, outcome=\"refused\",\n                                          effect=\"none\", elapsed_ms=0, confirmed=False,\n                                          auto_allowed=False, error_code=exc.error.code.value)\n            return Response.failure(req.id, exc.error, time.monotonic())\n        # The session's memory space decides which learned memory every\n        # request of the session reads and writes (memspace.py).\n        space_token = None\n        if session is not None and session.memory_space != \"default\":\n            space_token = self._active_space.set(self.space(session.memory_space))\n        try:\n            if not physical:\n                return self._handle(req)\n            with self._surface_lock:\n                token = None\n                if session is not None:\n                    if session.rb_surface is None:\n                        from .rb import RbSurface\n                        session.rb_surface = RbSurface()\n                        session.rb_surface.home = self.home\n                        session.rb_surface.memory = self.browser_memory\n                        session.rb_surface.research = self.research\n                        session.rb_surface.perception = self.perception\n                    session.rb_surface.focus_windows = self.policy.steal_focus\n                    token = self._active_rb.set(session.rb_surface)\n                try:\n                    return self._handle(req)\n                finally:\n                    if token is not None:\n                        self._active_rb.reset(token)\n        finally:\n            if space_token is not None:\n                self._active_space.reset(space_token)\n\n    def _handle(self, req: Request) -> Response:\n        with self.events.step(req.session or 'system', req.session or req.id or 'system'):\n            return self._handle_step(req)\n\n    def _handle_step(self, req: Request) -> Response:\n        self._reload_policy_if_changed()\n        started = time.monotonic()\n        session: Session | None = None\n        decision = Decision(True)\n        confirmed = False\n        auto_allowed = False\n        proc: str | None = None\n        url: str | None = None\n        target_desc: str | None = None\n        dispatch_state = EffectState.PENDING\n        action_id = req.id or secrets.token_hex(8)\n        # db1: set before any refusal, so the failure reporting below can\n        # always name them (live db1: an UnboundLocalError in the reporting).\n        identity: dict[str, Any] | None = None\n        read_only = self.permissions.risk_of(req.method) is Risk.READ\n\n        def dispatch(active_session: Session | None) -> dict[str, Any]:\n            nonlocal dispatch_state\n            # sp1: browser work stops the whole desktop tool; a desktop action starts it again.\n            from .desktop import surface\n            surface.enter(req.method, list(self.sessions.values()), serving=self._server is not None)\n            if active_session is not None and req.method.startswith('desktop.'):\n                self.environment.inspect_environment()\n            p = self.events.context()\n            action = Action(action_id, p.step_id, ActionKind.CONTROL,\n                SemanticTarget('v1-handler:' + req.method), (Parameter('method', req.method),),\n                IntentClass.UNKNOWN, Sensitivity.UNKNOWN, BudgetEstimate())\n            if req.method not in self.NOT_AUDITED:\n                self.events.emit(EventKind.ACTION_DISPATCHED, action)\n            dispatch_state = EffectState.DISPATCHED\n            from .desktop.actions import deliver\n            # Surprise-window baseline (desktop verbs only): a modal raised by\n            # the action itself is the classic silent blocker (measured\n            # 2026-10-06: Excel's 'There's a problem with this formula'\n            # dialog swallowed every later input while nothing failed). Win32\n            # enumeration on this thread; no COM, so the UIA STA rule holds.\n            surprise_base = (_surprise_baseline()\n                             if req.method.startswith(\"desktop.\") else None)\n            from .desktop import driver_backend\n            with driver_backend.use_session(active_session.id if active_session else None):\n                result = deliver(\n                    lambda: self._handlers[req.method](active_session, req.params),\n                    quiet=not self.policy.steal_focus,\n                    interactive_fallback=(req.method.startswith('desktop.') and\n                                          self.policy.desktop_interactive_fallback),\n                    annotate=req.method.startswith('desktop.'),\n                    # b14: focusing is the request itself; it is not handed back (CUA bring_to_front).\n                    restore_foreground=req.method != \"desktop.focus\")\n            if surprise_base is not None and isinstance(result, dict):\n                appeared = _surprise_windows(surprise_base, proc)\n                if appeared:\n                    result[\"surprise_window\"] = appeared\n            return result\n\n        try:\n            if req.method not in self._handlers:\n                raise ProtocolError(\n                    ErrorCode.UNSUPPORTED, f\"unknown method {req.method!r}\",\n                    hint=\"Run `auto --help` for available commands.\")\n            # b5t7: a desktop call without a toolspec-required parameter is\n            # refused before target lookup or approval, effect none - CUA\n            # answers a missing argument with a plain error (impl_.rs:4408);\n            # it used to crash in the handler as internal, effect unknown.\n            # Browser verbs keep their behaviour (owner warning W52).\n            if req.method.startswith(\"desktop.\"):\n                for key in _required_params(req.method):\n                    if (req.params or {}).get(key) is None:\n                        raise ProtocolError(\n                            ErrorCode.UNSUPPORTED, f\"{req.method} requires {key}\",\n                            hint=\"See the tool's parameters in SKILL.md.\")\n\n            needs_session = req.method.startswith((\"desktop.\", \"browser.\",\n                                                   \"human.\", \"rb.\"))\n            sessionless = {Method.DESKTOP_WINDOWS.value,\n                           Method.BROWSER_LIST.value,\n                           Method.DESKTOP_APPS.value,\n                           Method.DESKTOP_TABLE_READ.value,\n                           Method.DESKTOP_TABLE_APPEND.value,\n                           Method.DESKTOP_TABLE_EXPORT.value,\n                           Method.DESKTOP_COPY.value,\n                           Method.DESKTOP_REPORT.value} | {\n                m.value for m in Method if m.value.startswith(\"rb.\")}\n            if req.session or (needs_session and req.method not in sessionless):\n                session = self.get_session(req.session)\n\n            # Resolve the target under the session lock: an observation\n            # running concurrently would otherwise swap the ref store between\n            # this lookup and the action, which is exactly the stale-target\n            # class of bug the ref generation exists to prevent.\n            # sp1 (the owner's design): the desktop tool never works inside a\n            # browser window - refused here, before approval and any input.\n            from .desktop import surface\n            if session is not None:\n                with session.lock:\n                    proc, title, url = self._target_of(session, req)\n                    surface.refuse_inside_browser(session, req.method, req.params,\n                                                  foreground=self._server is not None)\n            else:\n                proc, title, url = self._target_of(session, req)\n                surface.refuse_inside_browser(session, req.method, req.params,\n                                              foreground=self._server is not None)\n            target_desc = \" / \".join(\n                x for x in (proc, title, _loggable(url)) if x) or \"?\"\n            decision = self.permissions.check(req.method, process=proc,\n                                              title=title, url=url)\n            self.permissions.enforce(decision, req.method)\n\n            if decision.needs_confirmation:\n                # \"Always allow\" in the dashboard answers for the rest of\n                # this run only; a new task asks again.\n                auto_allowed = self.run_control.auto_approves()\n                if not auto_allowed:\n                    self.run_control.note(\"approval\", scope=\"asked\", method=req.method,\n                                          app=proc, reason=decision.reason)\n                    self.run_control.open_dashboard(\"approval\")\n                # b25e (owner decision: ONE ask per batch in every mode):\n                # for desktop.batch the method-level ask itself lists every\n                # step, so its grant covers the steps and the handler skips\n                # its own combined ask. Every other method's detail stays\n                # byte-identical.\n                if req.method == \"desktop.batch\":\n                    from .desktop.batch import describe_steps\n                    detail, mirror_detail = describe_steps(session, req.params)\n                else:\n                    detail = f\"{req.method} on {target_desc} — {decision.reason}\"\n                    mirror_detail = None\n                granted = auto_allowed or self.confirmations.ask(\n                    session=req.session, method=req.method,\n                    detail=detail, mirror_detail=mirror_detail,\n                    timeout=self.policy.confirm_timeout_s)\n                if not granted:\n                    raise ProtocolError(\n                        ErrorCode.CONFIRMATION_DECLINED,\n                        f\"{req.method} was not approved\",\n                        hint=\"The user declined or did not answer in time. \"\n                             \"Respect that: do not repeat this request.\")\n                confirmed = True\n                # A confirmation can wait a minute for a human, and the world\n                # does not pause for it. The target as approved may no longer\n                # be the target about to act, so the policy decision is\n                # re-derived from the current state — a tab the user switched\n                # to, a URL the page redirected to — before anything runs.\n                if session is not None:\n                    with session.lock:\n                        proc, title, url = self._target_of(session, req)\n                else:\n                    proc, title, url = self._target_of(session, req)\n                target_desc = \" / \".join(\n                    x for x in (proc, title, _loggable(url)) if x) or \"?\"\n                decision = self.permissions.check(req.method, process=proc,\n                                                  title=title, url=url)\n                self.permissions.enforce(decision, req.method)\n\n            if session is not None:\n                session.touch()\n                memory_hints = []\n                with session.lock:\n                    proc, title, url = self._target_of(session, req)\n                    self.permissions.enforce(self.permissions.check(\n                        req.method, process=proc, title=title, url=url), req.method)\n                    if req.method.startswith((\"rb.\", \"browser.\", \"desktop.\")):\n                        # db1: what the run's record needs to find the refs again\n                        # on a replay (trajectory.py); read before the action.\n                        from .trajectory import ref_identity, window_identity\n                        identity = ref_identity(session.ref_store, req.params)\n                        win = window_identity(req.params, proc, title)      # db7 Item J: a \"#handle\" window's identity\n                        if win:\n                            identity = {**(identity or {}), **win}\n                        from urllib.parse import urlsplit\n                        query = \" \".join(filter(None, (req.method, proc, urlsplit(url or \"\").hostname)))\n                        try:\n                            memory_hints = [{\"source\": doc.source, \"kind\": doc.kind,\n                                             \"confidence\": doc.confidence, \"score\": round(score, 3),\n                                             \"evidence\": doc.text[:200], \"trust\": \"advisory\"}\n                                            for doc, score in self.mind.recall_experience(query, k=3)]\n                        except (ValueError, OSError, ImportError):\n                            pass\n                    # b25e: communicate the method-level grant to the\n                    # batch handler for THIS request only (a contextvar set\n                    # and reset around the dispatch call; per-thread, so it\n                    # cannot leak to a concurrent request or the next one).\n                    _grant_token = None\n                    if req.method == \"desktop.batch\" and confirmed:\n                        from .desktop.batch import (\n                            reset_request_ask_granted, set_request_ask_granted)\n                        _grant_token = set_request_ask_granted()\n                    try:\n                        result = dispatch(session)\n                    finally:\n                        if _grant_token is not None:\n                            reset_request_ask_granted(_grant_token)\n                    if memory_hints:\n                        result[\"memory_hints\"] = memory_hints\n                    if (proc and req.method in ('desktop.click', 'desktop.type', 'desktop.set_value')\n                            and result.get('verified') is True and result.get('method')):\n                        try:\n                            self.appmemory.note_method(proc, req.method.split('.')[1],\n                                str(result['method']), proven_by=self.events.context().step_id)\n                        except (OSError, ValueError) as memory_error:\n                            result['app_memory_warning'] = type(memory_error).__name__\n                    session.touch()\n            else:\n                result = dispatch(None)\n\n            if req.method not in self.NOT_AUDITED:\n                self.audit.record(\n                    session=req.session, method=req.method, params=req.params,\n                    outcome=\"ok\",\n                    effect_state=str(result.get(\"effect_state\", \"none\")),\n                    elapsed_ms=int((time.monotonic() - started) * 1000),\n                    confirmed_by_user=confirmed, target=target_desc,\n                    result=result)\n            self._note_run(req, \"ok\", str(result.get(\"effect_state\", \"none\")), started,\n                           confirmed, auto_allowed, proc, url, result=result, identity=identity,\n                           read_only=read_only, session_obj=session)\n            if session and req.method.startswith((\"rb.\", \"browser.\", \"desktop.\")):\n                from .contracts.workflow_memory import WorkflowFeedback, WorkflowOutcome\n                from .orchestrator.workflow_memory import recall_wire\n                memory_write = self.workflow_evidence.remember_evidence(WorkflowFeedback(\n                    session.id, req.method, WorkflowOutcome.VERIFIED if result.get('verified') is True\n                    else WorkflowOutcome.UNKNOWN))\n                result['workflow_memory_write'] = memory_write.status.value\n                result[\"workflow_memory\"] = recall_wire(self.workflow_evidence, session.id, 3)\n            if session is not None and req.method not in self.NOT_AUDITED:\n                # db1: the owner's button presses since this session's last\n                # reply, so the agent can say what the owner did.\n                controls, session.control_seq = self.run_control.owner_controls_since(session.control_seq)\n                if controls:\n                    result[\"owner_controls\"] = controls\n            return Response.success(req.id, result, started)\n\n        except ProtocolError as exc:\n            try:\n                if session is not None and dispatch_state is EffectState.DISPATCHED:\n                    from .contracts.workflow_memory import WorkflowFeedback, WorkflowOutcome\n                    self.workflow_evidence.remember_evidence(WorkflowFeedback(\n                        session.id, req.method,\n                        WorkflowOutcome.UNKNOWN if exc.error.effect_state is LegacyEffectState.UNKNOWN\n                        else WorkflowOutcome.FAILED))\n                if req.method not in self.NOT_AUDITED:\n                    self.audit.record(\n                        session=req.session, method=req.method, params=req.params,\n                        outcome=\"error\",\n                        effect_state=exc.error.effect_state.value,\n                        elapsed_ms=int((time.monotonic() - started) * 1000),\n                        error=exc.error.message, confirmed_by_user=confirmed,\n                        target=target_desc)\n                refusal = (exc.error.details or {}).get(\"delivery_refusal\") or {}\n                self._note_run(req, \"error\", exc.error.effect_state.value, started, confirmed,\n                               auto_allowed, proc, url, error_code=exc.error.code.value,\n                               refusal=refusal.get(\"code\"), identity=identity, read_only=read_only,\n                               session_obj=session)\n            except Exception as reporting_error:\n                # Preserve the original action's effect even if reporting also\n                # fails. Expose the secondary failure without private prose.\n                exc.error.details = {**(exc.error.details or {}), 'secondary_failure': {\n                    'component': 'failure_reporting', 'type': type(reporting_error).__name__}}\n            return Response.failure(req.id, exc.error, started)\n        except Exception as exc:  # pragma: no cover - defensive\n            # A lost reply after handler entry can follow an actual side effect.\n            # The response and audit must agree; NEVER advertise safe retry.\n            state = (LegacyEffectState.UNKNOWN if dispatch_state is EffectState.DISPATCHED\n                     else LegacyEffectState.NONE)\n            err = RpcError(ErrorCode.INTERNAL, f\"{type(exc).__name__}: {exc}\", effect_state=state)\n            if req.method not in self.NOT_AUDITED:\n                try:\n                    p = self.events.context()\n                    failure = Failure(FailureKind.LOGICAL, p.step_id, type(exc).__name__,\n                                      False, None, p)\n                    self.events.emit(EventKind.FAILURE, failure)\n                    self.events.emit(EventKind.EFFECT, Effect(action_id,\n                        EffectState.UNKNOWN if state is LegacyEffectState.UNKNOWN else EffectState.REJECTED,\n                        None, (), p))\n                    self.audit.record(\n                        session=req.session, method=req.method, params=req.params,\n                        outcome=\"crash\", effect_state=state.value,\n                        elapsed_ms=int((time.monotonic() - started) * 1000),\n                        error=type(exc).__name__, target=target_desc)\n                    self._note_run(req, \"crash\", state.value, started, confirmed, auto_allowed,\n                                   proc, url, error_code=ErrorCode.INTERNAL.value)\n                except (OSError, RuntimeError, ValueError, TypeError):\n                    # A broken journal is itself a failure. Do not let a second\n                    # persistence error erase the authoritative UNKNOWN response.\n                    pass\n            return Response.failure(req.id, err, started)\n\n    @staticmethod\n    def _recordable(method: str) -> bool:\n        \"\"\"A step of the workflow: what the tools did, not the session's own\n        start and stop nor the control, audit and history reads.\"\"\"\n        from .runcontrol import stage_of\n        return stage_of(method, \"\", None) != \"control\" and not method.startswith(\"session.\")\n\n    def _note_run(self, req: Request, outcome: str, effect: str, started: float,\n                  confirmed: bool, auto_allowed: bool, proc: str | None, url: str | None,\n                  **extra: Any) -> None:\n        \"\"\"One finished request on the dashboard's live feed (runcontrol.py),\n        and the run bookkeeping that follows from it. Never raises.\"\"\"\n        if req.method in self.NOT_AUDITED or req.method.startswith(\"_run.\"):\n            return\n        identity = extra.pop(\"identity\", None)\n        read_only = bool(extra.pop(\"read_only\", False))\n        session_obj = extra.pop(\"session_obj\", None)\n        try:\n            self.run_control.note_request(\n                method=req.method, session=req.session, outcome=outcome, effect=effect,\n                elapsed_ms=int((time.monotonic() - started) * 1000), confirmed=confirmed,\n                auto_allowed=auto_allowed, target=(proc, url), **extra)\n            if self._recordable(req.method):\n                # db1: the run's step-by-step record (trajectory.py).\n                result = extra.get(\"result\") or {}\n                self.run_control.record_turn(\n                    tool=req.method, arguments=req.params, outcome=outcome, effect=effect,\n                    result=result, error=extra.get(\"error_code\"),\n                    elapsed_ms=int((time.monotonic() - started) * 1000), session=req.session,\n                    client=({**session_obj.client, **({\"agent\": session_obj.agent} if session_obj.agent else {})}\n                            if session_obj is not None else None),      # db7: the step names its agent\n                    target=identity, read_only=read_only, delivery=result.get(\"delivery\"))\n            if outcome != \"ok\":\n                return\n            if req.method in (\"desktop.open_app\", \"rb.open\"):\n                self.run_control.note_opened(req.method, extra.get(\"result\") or {})\n            if req.method == \"session.start\":\n                self.run_control.begin(\"session\", None, session=extra.get(\"result\", {}).get(\"session_id\"))\n                self.run_control.open_dashboard(\"session\")\n            elif req.method == \"site.replay\":\n                self.run_control.begin(\"recipe\", str(req.params.get(\"name\") or \"\"),\n                                       site=req.params.get(\"host\"))\n                self.run_control.open_dashboard(\"recipe\")\n            elif req.method == \"session.stop\":\n                self.run_control.end_if_idle(len(self.sessions))\n        except Exception:                       # noqa: BLE001 - a view never breaks a request\n            pass\n\n    def _target_of(self, session: Session | None,\n                   req: Request) -> tuple[str | None, str | None, str | None]:\n        \"\"\"Identify what an action would hit, for the policy check.\n\n        Returns (process, title, url) naming what the action would hit, for\n        the approval prompt and the audit/run notes. For a navigation the URL\n        is where it is going; for anything else it is the page the verb acts\n        on.\n        \"\"\"\n        proc: str | None\n        title: str | None\n        ref = req.params.get(\"ref\")\n        if session and session.ref_store and ref and not \\\n                req.method.startswith(\"browser.\"):\n            try:\n                entry = session.ref_store.resolve(ref)\n                return entry.process or None, entry.window_title or None, None\n            except ProtocolError:\n                pass\n        if req.method == Method.DESKTOP_OPEN_APP.value:\n            cmd = str(req.params.get(\"command\", \"\"))\n            return Path(cmd).name or cmd, None, None\n        if req.method == Method.DESKTOP_QUIT_APP.value:\n            # Name the explicit target for the existing approval prompt and run notes.\n            proc = (f\"pid {req.params['pid']}\" if req.params.get(\"pid\") is not None\n                    else str(req.params.get(\"process\", \"\")))\n            return proc or None, None, None\n        if req.method == Method.DESKTOP_INVOKE_MENU.value:\n            # B17: name the window and the menu path straight from the\n            # request (purely descriptive, exactly like quit_app's pid\n            # naming - no window lookup seam for a window_id).\n            path = req.params.get(\"path\")\n            labels = \" > \".join(str(item) for item in path) if isinstance(path, list) else \"\"\n            return (f\"window {req.params.get('window_id')} menu {labels}\"\n                    if labels else None), None, None\n        if req.method == Method.DESKTOP_CLIPBOARD_WRITE.value:\n            # B19: name the VALUE KIND, never the content - the ask detail\n            # mirrors verbatim into confirmations.json (daemon.py:209-212),\n            # so clipboard text must not flow through here.\n            if isinstance(req.params.get(\"text\"), str):\n                return \"clipboard text\", None, None\n            for key, kind in ((\"image_path\", \"clipboard image file\"),\n                              (\"file_path\", \"clipboard file URL\")):\n                value = req.params.get(key)\n                if isinstance(value, str) and value:\n                    return f\"{kind} {value}\", None, None\n            return \"the clipboard\", None, None\n        if req.method == Method.DESKTOP_SET_WINDOW_FRAME.value:\n            # B18: name the WINDOW, never the coordinates (the ask detail\n            # mirrors verbatim into confirmations.json and the four frame\n            # numbers are content-ish; the b19 name-the-kind precedent).\n            return f\"window {req.params.get('window_id')}\", None, None\n        if req.method in (Method.DESKTOP_CLICK_AT.value,) and not (\n                req.params.get(\"window\") or req.params.get(\"title\")):\n            # A click at a bare screen position hits whatever window is\n            # there, so the approval prompt and the audit/run notes must\n            # name that window — not the last window the session touched.\n            # Naming only: no permission check happens here (owner decision\n            # 2026-10-11 removed the deny lists; this branch never refuses).\n            from .desktop.vision import process_at_point\n            try:\n                proc, title = process_at_point(int(req.params.get(\"x\", 0)),\n                                               int(req.params.get(\"y\", 0)))\n            except Exception:\n                proc, title = None, None\n            return proc, title, None\n        if req.method.startswith(\"rb.\"):\n            # The URL the verb would act on, for the approval prompt, the\n            # audit/run notes and memory recall.\n            url = req.params.get(\"url\")\n            if isinstance(url, str) and url.strip():\n                return None, None, url\n            try:\n                return None, None, self.rb.url_of(req.params.get(\"tab_id\"))\n            except Exception:\n                return None, None, None\n        if req.method.startswith(\"browser.\"):\n            url = req.params.get(\"url\")\n            if isinstance(url, str) and url.strip():\n                return None, None, url\n            # Honour --tab-id. Every browser verb acts on the tab named\n            # by tab_id (handlers._page_t), so the target must name that\n            # tab's page, not whichever page was active last.\n            page = None\n            tab = req.params.get(\"tab_id\")\n            if session is not None and tab:\n                page = (getattr(session, \"browser_pages\", None)\n                        or {}).get(str(tab))\n            if page is None:\n                page = getattr(session, \"browser_page\", None) if session else None\n            if page is not None and page.current_url:\n                return None, None, page.current_url\n            return None, None, None\n        win = req.params.get(\"window\") or req.params.get(\"title\")\n        if win:\n            # Bind the real target for the approval prompt and the audit/run\n            # notes: the process and the window's actual title (not the\n            # selector string). Win32 only: no COM on this thread, and no\n            # driver access here, so `window_identity` must stay a local\n            # lookup. Titles keep process_for_window's first-match rule, so\n            # which window a selector binds is unchanged.\n            from .desktop.actions import window_identity\n            try:\n                ident = window_identity(str(win))\n            except Exception:\n                ident = None\n            if ident:\n                return ident[\"process\"] or None, ident[\"title\"] or str(win), None\n            return None, str(win), None\n        if session and session.last_window:\n            return None, session.last_window, None\n        return None, None, None\n\n    # --- handlers -----------------------------------------------------------\n\n    def _install_handlers(self) -> None:\n        from . import handlers\n        handlers.register(self)\n\n    def register(self, method: str,\n                 fn: Callable[[Session | None, dict[str, Any]], dict[str, Any]]) -> None:\n        self._handlers[method] = fn\n\n    def status(self) -> dict[str, Any]:\n        return {\n            \"version\": VERSION,\n            \"protocol_version\": PROTOCOL_VERSION,\n            \"pid\": os.getpid(),\n            \"uptime_s\": round(time.time() - self.started_at, 1),\n            \"port\": self.port,\n            \"home\": str(self.home),\n            \"permission_mode\": self.policy.mode.value,\n            \"quiet\": not bool(getattr(self.policy, \"steal_focus\", False)),\n            \"desktop_interactive_fallback\": self.policy.desktop_interactive_fallback,\n            \"sessions\": [s.info() for s in self.sessions.values()],\n            \"pending_confirmations\": self.confirmations.pending(),\n            \"reaped_on_startup\": getattr(self, \"reaped\", None),\n            \"idle_timeout_s\": self.idle_timeout_s,\n            \"run_control\": self._run_summary(),\n        }\n\n    def _run_summary(self) -> dict[str, Any]:\n        \"\"\"The Kgrow.io view of `auto status` (DB-07).\"\"\"\n        snap = self.run_control.snapshot()\n        try:\n            from .dashboard.launch import running\n            dashboard = running(self.home) is not None\n        except Exception:                       # noqa: BLE001\n            dashboard = False\n        run = snap.get(\"run\") or {}\n        return {\"state\": snap[\"state\"], \"run\": run.get(\"kind\"), \"name\": run.get(\"name\"),\n                \"always_allow\": snap[\"always_allow\"], \"repeat\": snap[\"repeat\"],\n                \"progress\": snap.get(\"progress\"), \"dashboard_open\": dashboard}\n\n    # --- serving ------------------------------------------------------------\n\n    def _ensure_desktop_shortcut(self) -> None:\n        \"\"\"Only the owner's real home manages the shortcuts (shortcut.manages); a test or dev home never writes.\"\"\"\n        try:\n            from . import relocation\n            from .dashboard import shortcut\n            root = relocation.checkout_root()\n            if root is not None and shortcut.manages(self.home):\n                shortcut.ensure_desktop(root)\n        except Exception:                        # noqa: BLE001 - a shortcut never stops the daemon\n            pass\n\n    def serve_forever(self, port: int = 0) -> None:\n        daemon = self\n\n        class Handler(socketserver.StreamRequestHandler):\n            timeout = 300\n\n            def handle(self) -> None:\n                try:\n                    for raw in iter(lambda: self.rfile.readline(4 * 1024 * 1024 + 1), b\"\"):\n                        if len(raw) > 4 * 1024 * 1024:\n                            return\n                        line = raw.decode(\"utf-8\", \"replace\").strip()\n                        if not line:\n                            continue\n                        try:\n                            payload = json.loads(line)\n                        except json.JSONDecodeError:\n                            continue\n                        if not isinstance(payload, dict):\n                            return\n                        # Constant-time: a plain != leaks the token\n                        # one byte at a time to a local attacker\n                        # willing to time the comparison.\n                        if not secrets.compare_digest(\n                                str(payload.get(\"token\") or \"\"),\n                                daemon.token):\n                            self.wfile.write(\n                                (json.dumps({\"ok\": False, \"error\": {\n                                    \"code\": \"permission_denied\",\n                                    \"message\": \"bad or missing token\"}}) + \"\\n\")\n                                .encode())\n                            return\n                        req = Request(method=payload.get(\"method\", \"\"),\n                                      params=payload.get(\"params\") or {},\n                                      id=payload.get(\"id\", \"\"),\n                                      session=payload.get(\"session\"))\n                        resp = daemon.handle(req)\n                        self.wfile.write(resp.to_line().encode(\"utf-8\"))\n                        self.wfile.flush()\n                except (ConnectionResetError, BrokenPipeError, socket.timeout):\n                    pass\n\n        class Server(socketserver.ThreadingTCPServer):\n            allow_reuse_address = True\n            daemon_threads = True\n\n        # Reap browsers orphaned by a previous crash before accepting work:\n        # a leftover Chrome holds the profile lock and the next `browser open`\n        # fails with an opaque timeout.\n        try:\n            from .browser import reaper\n            self.reaped = reaper.reap(self.home)\n        except Exception:\n            self.reaped = {\"checked\": 0, \"reaped\": 0, \"skipped\": 0}\n\n        self._server = Server((\"127.0.0.1\", port), Handler)\n        self.port = self._server.server_address[1]\n        # perf1: the renderer starts with the serving daemon, not inside its first action (CUA run_on_thread).\n        from .desktop import overlay\n        overlay.warm()\n        self._write_endpoint()\n        threading.Thread(target=self._idle_loop, daemon=True,\n                         name=\"idle-reaper\").start()\n        # db7 (owner order 2026-10-31): every start looks at the Desktop and writes the missing dashboard shortcut\n        threading.Thread(target=self._ensure_desktop_shortcut, daemon=True, name=\"desktop-shortcut\").start()\n        # Only a daemon that serves a real owner opens the dashboard window;\n        # a Daemon built in a test never does (dashboard/launch.py).\n        from .dashboard.launch import open_in_background\n        self.run_control.dashboard_opener = lambda why: open_in_background(self.home, why)\n        try:\n            self._server.serve_forever(poll_interval=0.3)\n        finally:\n            self._cleanup_endpoint()\n\n    def _write_endpoint(self) -> None:\n        # code_root: the folder whose code this daemon runs. A client started\n        # from a moved project uses it to replace a daemon whose folder is\n        # gone (relocation.py); the root is also recorded so `auto relocate`\n        # can recognise links that still name a former location.\n        from . import relocation\n        code_root = Path(__file__).resolve().parent\n        data = {\"port\": self.port, \"token\": self.token, \"pid\": os.getpid(),\n                \"version\": VERSION, \"started_at\": self.started_at,\n                \"code_root\": str(code_root)}\n        relocation.remember_root(self.home, relocation.checkout_root(code_root))\n        p = endpoint_file(self.home)\n        tmp = p.with_suffix(\".tmp\")\n        tmp.write_text(json.dumps(data, indent=2), encoding=\"utf-8\")\n        _restrict_to_owner(tmp)\n        os.replace(tmp, p)\n        _restrict_to_owner(p)\n\n    def _cleanup_endpoint(self) -> None:\n        from .paths import release_endpoint\n        release_endpoint(endpoint_file(self.home), self.token)   # never a successor's file\n\n    def shutdown(self) -> None:\n        self._stop_idle.set()\n        for sid in list(self.sessions):\n            try:\n                self.stop_session(sid)\n            except Exception:\n                pass\n        try:\n            from .desktop import driver_backend\n            driver_backend.shutdown()\n        except Exception:\n            pass\n        try:\n            from .desktop.executor import shutdown as _uia_shutdown\n            _uia_shutdown()\n        except Exception:\n            pass\n        for durable in (\"events\", \"audit\"):\n            try:\n                getattr(self, durable).sync()   # a partly built daemon (tests) may lack either\n            except Exception:\n                pass\n        if self._server is not None:\n            # Delay the stop so the reply to `system.shutdown` is sent first: an\n            # immediate stop let the process exit mid-reply, and the caller saw\n            # WinError 10054 although the stop succeeded (measured 2026-10-05).\n            stopper = threading.Timer(0.5, self._server.shutdown)\n            stopper.daemon = True\n            stopper.start()\n\n    def set_mode(self, mode: str) -> dict[str, Any]:\n        try:\n            m = PermissionMode(mode)\n        except ValueError as exc:\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED, f\"unknown permission mode {mode!r}\",\n                hint=\"Use strict, guarded or full.\") from exc\n        self.policy.mode = m\n        save_policy(self.home, self.policy)\n        self._policy_mtime = 0.0\n        return {\"permission_mode\": m.value}\n");
